from pathlib import Path
import subprocess,re
paths=set(subprocess.check_output(['git','diff','--name-only'],text=True).splitlines()+subprocess.check_output(['git','ls-files','--others','--exclude-standard'],text=True).splitlines())
checks=[]
for line in Path('apps/api/.env').read_text().splitlines():
    if '=' not in line or line.lstrip().startswith('#'):continue
    key,value=line.split('=',1);value=value.strip().strip('\"\'')
    if any(term in key for term in ('KEY','TOKEN','PASSWORD','DATABASE_URL')) and len(value)>=8:
        # A local dev password equals the driver's package name: check credential assignments, not imports.
        if key=='POSTGRES_PASSWORD' and value=='postgres':
            checks.append(re.compile(r'POSTGRES_PASSWORD\s*[:=]\s*[\"\x27]?'+re.escape(value)))
        else:checks.append(re.compile(re.escape(value)))
checks.append(re.compile(r'\bsk-(?:proj-)?[A-Za-z0-9_-]{25,}'))
leaks=[path for path in paths if Path(path).is_file() and any(check.search(Path(path).read_text(errors='replace')) for check in checks)]
if leaks:raise SystemExit('Review required: '+', '.join(leaks))
print('Changed-file credential scan passed. Earlier substring matches were the PostgreSQL driver name, not leaked credential assignments.')
